    if ((n - 1) * (k + 3)) > (x + k) or k < 0:
        return -1
    else:
        # Calculate the target elements sum
        total_elements_sum = k * 2 + min(x, n - k)

        for i in range(k + 1):
            while n - (k - i) + i + x >= max(0, 1 + i):  
                n -= i

        if n < k:  
            return -1

        # Calculate the MEX of this array
        mex = [0] * k
        for idx in range(n):
            if idx == k:
                continue
            mex[idx] += min(x, (n - k) + 1)

        total_elements_sum %= sum(mex)  # To make it a valid number

        max_sum = n * max(0, k - mex[0])
        for i in range(1, k):
            # Update the excess at each step after subtracting i
            x -= x % (i + 2)

            if x < 0:
                break

            total_elements_sum += min(n - k + i, max(i + 1, n - k)) * i

        return (mex[0] + total_elements_sum) // max(0, max(1, n // min(k, n)))
