                        return min_moves + 2 
            cuts -= 1

    def count():
        nonlocal rows, cols
        res = [None] * (rows + 1)
        for i in range(rows):
            for j in range(cols):
                if a[i][j]:
                    res[j+1] += 1

        return 0 if all(res[i]) == 0 for i in res[:-1])

    cut_grid(a[:] | [[0, count()]] #[[count()]])
    return min_moves

